import React from "react"
import styled from "styled-components";

const ChequeText = styled.text`
    font-weight: bold;

`

export default function ChequeTemplate({amount, to}) {


    try {
        return <svg id="CHEQUE" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 452.46 159.03">
            <image id="ArrierePlan" width="1781" height="626" transform="scale(.25)"
                   href="data:image/png;base64,"/>
            <ChequeText transform="translate(379 74)">
                <tspan x="0" y="0">{amount}</tspan>
            </ChequeText>
            <ChequeText transform="translate(20.01 119.04)">
                {to}
            </ChequeText>
        </svg>
    } catch (e) {
        console.error('>>>', e)
        return <div>COUCOU</div>

    }
}